contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take parameters: caller must be the owner (this contract deployed c), receiver nonzero, amount>0
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver != address(0));
        require(amount > 0);
        // Ensure this contract has enough balance to forward the transfer from c if needed
        // c was deployed by this contract's constructor (per harness), so this contract is owner of c.
        require(address(this).balance >= 0);

        // Record balances before the call
        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver.balance;

        bool reverted;
        // Call sendTo as owner (this contract is owner of c). sendTo does not accept value, but it will transfer from c.
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = receiver.balance;

        // If the call did not revert, then c's balance must have decreased by exactly amount and receiver increased by exactly amount.
        // If it reverted, balances must be unchanged.
        assert((!reverted && afterC + amount == beforeC && afterReceiver == beforeReceiver + amount) || (reverted && afterC == beforeC && afterReceiver == beforeReceiver));
    }

    receive() external payable {}
}

